from typing import Any
from typing import TextIO
import csv
import io
import pandas as pd

REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')  # assumption: adjust to your real role list
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        role = (row.get('role') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if not role:
            problems.append('role is required')
        elif role not in VALID_ROLES:
            problems.append(f"role must be one of: {', '.join(VALID_ROLES)}")
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'role': role, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def validate_upload(content: bytes, filename: str, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Validate an uploaded users CSV/xlsx.

    Returns (valid_users, bad_rows); each bad row is {"row": <spreadsheet row
    number, header = 1>, "errors": [reasons...]}. All problems are reported.
    """
    if filename.lower().endswith(('.xlsx', '.xlsm')):
        try:
            # Read everything as text so IDs/ages are not coerced, then reuse
            # the reviewed CSV validator so both formats behave identically.
            df = pd.read_excel(io.BytesIO(content), engine='openpyxl', dtype=str,
                               keep_default_na=False, nrows=max_rows + 1)
        except Exception:
            return ([], [{'row': 1, 'errors': ['could not read file as xlsx']}])
        text = df.to_csv(index=False)
    else:
        try:
            text = content.decode('utf-8-sig')
        except UnicodeDecodeError:
            return ([], [{'row': 1, 'errors': ['file is not valid UTF-8 text']}])
    return import_users(text, max_rows=max_rows)


# ---------------------------------------------------------------- tests ----
def _csv(*lines: str) -> bytes:
    return ('\n'.join(lines) + '\n').encode()


def test_valid_csv_has_no_errors():
    data = _csv('name,email,role,age', 'Ann,ann@example.com,Admin,30', 'Bob,bob@example.com,viewer,')
    valid, errors = validate_upload(data, 'users.csv')
    assert errors == []
    assert [u['email'] for u in valid] == ['ann@example.com', 'bob@example.com']
    assert valid[0]['role'] == 'admin' and valid[1]['age'] is None


def test_reports_every_bad_row_with_reasons():
    data = _csv(
        'name,email,role,age',
        'Ann,ann@example.com,admin,30',   # row 2 ok
        ',not-an-email,boss,200',         # row 3: many problems
        'Dup,ANN@example.com,viewer,',    # row 4: duplicate
        'Eve,eve@example.com,,',          # row 5: role missing
    )
    valid, errors = validate_upload(data, 'users.csv')
    by_row = {e['row']: e['errors'] for e in errors}
    assert len(valid) == 1
    assert set(by_row) == {3, 4, 5}
    assert 'name is required' in by_row[3]
    assert 'email is invalid' in by_row[3]
    assert any(m.startswith('role must be one of') for m in by_row[3])
    assert any(m.startswith('age') for m in by_row[3])
    assert by_row[4] == ['duplicate email']
    assert by_row[5] == ['role is required']


def test_missing_required_column():
    valid, errors = validate_upload(_csv('name,email', 'Ann,ann@example.com'), 'u.csv')
    assert valid == []
    assert errors == [{'row': 1, 'errors': ['missing columns: role']}]


def test_xlsx_matches_csv_behaviour(tmp_path):
    path = tmp_path / 'users.xlsx'
    pd.DataFrame({
        'Name': ['Ann', 'Bob', 'Cy'],
        'Email': ['ann@example.com', 'bad', 'ann@example.com'],
        'Role': ['editor', 'viewer', 'admin'],
    }).to_excel(path, index=False)
    valid, errors = validate_upload(path.read_bytes(), 'users.xlsx')
    assert [u['name'] for u in valid] == ['Ann']
    assert {e['row']: e['errors'] for e in errors} == {
        3: ['email is invalid'],
        4: ['duplicate email'],
    }


def test_row_cap_and_garbage_xlsx():
    rows = ['name,email,role'] + [f'U{i},u{i}@example.com,viewer' for i in range(5)]
    valid, errors = validate_upload(_csv(*rows), 'u.csv', max_rows=3)
    assert len(valid) == 3
    assert 'stopped' in errors[-1]['errors'][0]
    _, errors = validate_upload(b'not a zip', 'u.xlsx')
    assert errors[0]['errors'] == ['could not read file as xlsx']

